import React from "react";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { Container, Row, Col } from "react-bootstrap";
import { meta } from "../../content_option";
import { useLanguage } from "../../i18n/LanguageContext";

export const About = () => {
  const { t, language } = useLanguage();

  const expertiseItems = t('about.expertise.items');
  const serviceItems = t('about.services.items');
  const timelineEvents = t('about.timeline.events');

  const pageTitle = language === 'pt'
    ? "Sobre a Tyber.io | Consultoria de IA & Equipe de Especialistas"
    : "About Tyber.io | AI Consulting Firm & Expert Team";

  const pageDescription = language === 'pt'
    ? "Conheça a Tyber.io: consultoria premium de inteligência artificial fundada em 2019 em São Paulo. Especialistas em machine learning, NLP, visão computacional e automação inteligente."
    : "Meet Tyber.io: premium AI consulting firm founded in 2019 in São Paulo, Brazil. Experts in machine learning, NLP, computer vision, and intelligent automation.";

  return (
    <HelmetProvider>
      <section className="about-page" itemScope itemType="https://schema.org/AboutPage">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{pageTitle}</title>
          <meta name="description" content={pageDescription} />
          <link rel="canonical" href="https://tyber.io/about" />
          <meta property="og:title" content={pageTitle} />
          <meta property="og:description" content={pageDescription} />
          <meta property="og:url" content="https://tyber.io/about" />
          <meta property="og:type" content="website" />
          <meta name="twitter:title" content={pageTitle} />
          <meta name="twitter:description" content={pageDescription} />
        </Helmet>

        {/* Hero Section */}
        <div className="about-hero">
          <Container>
            <div className="about-hero__badge">
              <span className="badge-dot"></span>
              <span className="badge-text">{t('about.badge')}</span>
            </div>
            <h1 className="about-hero__title gradient-text">
              {t('about.hero.title')}
            </h1>
            <p className="about-hero__subtitle">
              {t('about.hero.subtitle')}
            </p>

            <div className="page-stats-row">
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('about.stats.projects.value')}</span>
                <span className="page-stat-card__label">{t('about.stats.projects.label')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('about.stats.specializations.value')}</span>
                <span className="page-stat-card__label">{t('about.stats.specializations.label')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('about.stats.years.value')}</span>
                <span className="page-stat-card__label">{t('about.stats.years.label')}</span>
              </div>
            </div>
          </Container>
        </div>

        {/* Mission Section */}
        <Container className="about-section">
          <Row className="justify-content-center">
            <Col lg={10}>
              <div className="mission-card">
                <h2 className="section-title">{t('about.mission.title')}</h2>
                <p className="mission-content">{t('about.mission.content')}</p>
              </div>
            </Col>
          </Row>
        </Container>

        {/* Expertise Section */}
        <Container className="about-section">
          <div className="section-header">
            <h2 className="section-title gradient-text">{t('about.expertise.title')}</h2>
          </div>
          <Row>
            {Array.isArray(expertiseItems) && expertiseItems.map((item, index) => (
              <Col lg={4} md={6} key={index} className="mb-4">
                <div className="expertise-card">
                  <div className="expertise-card__number">
                    {String(index + 1).padStart(2, '0')}
                  </div>
                  <h3 className="expertise-card__title">{item.name}</h3>
                  <div className="expertise-card__bar">
                    <div
                      className="expertise-card__bar-fill"
                      style={{ width: `${item.level}%` }}
                    >
                      <span className="expertise-card__percentage">{item.level}%</span>
                    </div>
                  </div>
                  <p className="expertise-card__description">{item.description}</p>
                </div>
              </Col>
            ))}
          </Row>
        </Container>

        {/* Services Section */}
        <Container className="about-section">
          <div className="section-header">
            <h2 className="section-title gradient-text">{t('about.services.title')}</h2>
          </div>
          <Row>
            {Array.isArray(serviceItems) && serviceItems.map((item, index) => (
              <Col lg={6} key={index} className="mb-4">
                <div className="service-card">
                  <div className="service-card__number">{item.number}</div>
                  <h3 className="service-card__title">{item.title}</h3>
                  <p className="service-card__description">{item.description}</p>
                </div>
              </Col>
            ))}
          </Row>
        </Container>

        {/* Timeline Section */}
        <Container className="about-section">
          <div className="section-header">
            <h2 className="section-title gradient-text">{t('about.timeline.title')}</h2>
          </div>
          <Row className="justify-content-center">
            <Col lg={10}>
              <div className="timeline">
                {Array.isArray(timelineEvents) && timelineEvents.map((event, index) => (
                  <div key={index} className="timeline-item">
                    <div className="timeline-item__marker"></div>
                    <div className="timeline-item__content">
                      <div className="timeline-item__year">{event.year}</div>
                      <h3 className="timeline-item__title">{event.title}</h3>
                      <p className="timeline-item__description">{event.description}</p>
                    </div>
                  </div>
                ))}
              </div>
            </Col>
          </Row>
        </Container>
      </section>
    </HelmetProvider>
  );
};
